/*
 * A396058  Number of partitions of n into 5 distinct parts containing the
 *          part 3.
 * https://oeis.org/A396058
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-1)+a(n-2)-2*a(n-5)+a(n-8)+a(n-9)-a(n-10), for n > 25.
 *            Initial values a(0)..a(25) are generated by brute force
 * Range:     u8 n <= 44, u16 n <= 223, u32 n <= 8532, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Static cache for memoized values */
static seq_t *cache = NULL;
static size_t cache_size = 0;   /* number of values computed */
static size_t cache_cap  = 0;   /* allocated capacity */

/* Generate the first 26 values (a(0)..a(25)) by enumeration of combinations */
static void init_base(void)
{
    /* Allocate a small buffer, will be enlarged later if needed */
    size_t init_cap = 32;
    cache = (seq_t*)malloc(init_cap * sizeof(seq_t));
    cache_cap = init_cap;
    for (size_t i = 0; i < init_cap; ++i) cache[i] = 0;

    /* Count partitions that contain 3 using 4 distinct other parts */
    seq_t base[26] = {0};
    for (int a = 1; a <= 25; ++a) if (a != 3)
        for (int b = a + 1; b <= 25; ++b) if (b != 3)
            for (int c = b + 1; c <= 25; ++c) if (c != 3)
                for (int d = c + 1; d <= 25; ++d) if (d != 3) {
                    int sum = a + b + c + d + 3;
                    if (sum <= 25) ++base[sum];
                }
    /* Copy computed values into cache */
    for (int i = 0; i <= 25; ++i) cache[i] = base[i];
    cache_size = 26;  /* we have values 0 .. 25 */
}

/* Ensure that cache[n] is computed */
static void ensure_cache(idx_t n)
{
    if (cache_size == 0) init_base();

    /* If we already have everything up to n, return */
    if ((idx_t)cache_size > n) return;

    /* Expand storage if necessary */
    size_t need = (size_t)n + 1;
    if (need > cache_cap) {
        size_t new_cap = cache_cap ? cache_cap : 32;
        while (new_cap < need) new_cap <<= 1;
        cache = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        cache_cap = new_cap;
    }

    /* Compute further terms using the recurrence */
    size_t start = cache_size;
    if (start < 26) start = 26;           /* recurrence only valid for n > 25 */
    for (size_t i = start; i <= (size_t)n; ++i) {
        /* Compute using signed 64‑bit intermediate arithmetic */
        long long val =
            (long long)cache[i-1] + (long long)cache[i-2]
          - 2LL * (long long)cache[i-5]
          + (long long)cache[i-8] + (long long)cache[i-9]
          - (long long)cache[i-10];
        cache[i] = (seq_t)val;
    }
    cache_size = (size_t)n + 1;
}

/* Public function requested by the judge */
seq_t a(idx_t n)
{
    ensure_cache(n);
    return cache[(size_t)n];
}
